import { NextRequest, NextResponse } from "next/server";
import { getOpenAIClient } from "@/server/services/llm";
import { getBillingTracker } from "@/server/services/billing";
import { getAuthUser } from "@/server/auth";

export async function POST(request: NextRequest) {
  try {
    const user = await getAuthUser(request);
    if (!user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const body = await request.json();
    const { prompt, systemPrompt, temperature = 0.7, maxTokens = 4000, model = "gpt-4o-mini" } = body;

    if (!prompt) {
      return NextResponse.json({ error: "Prompt is required" }, { status: 400 });
    }

    // Check monthly prompt limits
    const promptLimits = { Starter: 10, "Pro Growth": 30, Enterprise: 50 };
    const limit = promptLimits[user.plan as keyof typeof promptLimits] || 10;

    // In production, check actual usage from DB
    // For now, we'll track via billing

    const client = getOpenAIClient();
    const result = await client.generate({ prompt, systemPrompt, temperature, maxTokens, model });

    // Track usage
    getBillingTracker().recordLLMUsage(user.id, user.workspaceId, model, result.usage.promptTokens, result.usage.completionTokens, {
      type: "content_generation",
      promptPreview: prompt.slice(0, 100),
    });

    return NextResponse.json({
      success: true,
      content: result.content,
      usage: result.usage,
      model,
    });
  } catch (error) {
    console.error("Content Generation API error:", error);
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "Failed to generate content" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getAnthropicClient } from "@/server/services/llm";
import { getBillingTracker } from "@/server/services/billing";
import { getAuthUser } from "@/server/auth";

export async function POST(request: NextRequest) {
  try {
    const user = await getAuthUser(request);
    if (!user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const body = await request.json();
    const { content, instruction, format = "markdown", model = "claude-3-5-haiku" } = body;

    if (!content || !instruction) {
      return NextResponse.json({ error: "Content and instruction are required" }, { status: 400 });
    }

    // Check fix limits
    const fixLimits = { Starter: 5, "Pro Growth": 20, Enterprise: 50 };
    const limit = fixLimits[user.plan as keyof typeof fixLimits] || 5;

    const client = getAnthropicClient();
    const result = await client.modify({ content, instruction, format, model });

    // Track usage
    getBillingTracker().recordLLMUsage(user.id, user.workspaceId, model, result.usage.promptTokens, result.usage.completionTokens, {
      type: "gap_modifier",
      format,
    });

    return NextResponse.json({
      success: true,
      content: result.content,
      usage: result.usage,
      model,
    });
  } catch (error) {
    console.error("Gap Modifier API error:", error);
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "Failed to modify content" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getPaymentClient, calculateTransactionFee, estimateMonthlyCost } from "@/server/services/payments";
import { getAuthUser } from "@/server/auth";

export async function POST(request: NextRequest) {
  try {
    const user = await getAuthUser(request);
    if (!user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const body = await request.json();
    const { provider, plan, interval = "monthly", returnUrl, cancelUrl } = body;

    if (!provider || !plan) {
      return NextResponse.json({ error: "Provider and plan are required" }, { status: 400 });
    }

    const planPrices = { Starter: 4999, "Pro Growth": 12999, Enterprise: 29999 };
    const amount = planPrices[plan as keyof typeof planPrices];
    if (!amount) {
      return NextResponse.json({ error: "Invalid plan" }, { status: 400 });
    }

    const finalAmount = interval === "yearly" ? Math.round(amount * 12 * 0.8) : amount;
    const fee = calculateTransactionFee(finalAmount);
    const totalAmount = Math.round(finalAmount + fee);

    const orderId = `ord_${user.id}_${plan}_${interval}_${Date.now()}`;

    const client = getPaymentClient(provider);
    const result = await client.initiatePayment({
      provider,
      amount: totalAmount,
      currency: "NPR",
      orderId,
      customerInfo: {
        name: user.name,
        email: user.email,
        phone: user.profile?.phone || "",
      },
      returnUrl: returnUrl || `${process.env.NEXT_PUBLIC_APP_URL}/dashboard/settings?payment=success`,
      cancelUrl: cancelUrl || `${process.env.NEXT_PUBLIC_APP_URL}/pricing?payment=cancelled`,
      metadata: { plan, interval, userId: user.id },
    });

    return NextResponse.json({
      success: result.success,
      paymentUrl: result.paymentUrl,
      paymentId: result.paymentId,
      orderId,
      amount: finalAmount,
      fee,
      totalAmount,
      error: result.error,
    });
  } catch (error) {
    console.error("Payment Initiation API error:", error);
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "Failed to initiate payment" },
      { status: 500 }
    );
  }
}

"use client";

import { useState, useEffect } from "react";
import { Panel } from "@/components/dashboard/panel";
import { formatINR } from "@/lib/format";

interface BillingSummary {
  period: { start: string; end: string };
  totalCostUsd: number;
  totalCostNpr: number;
  breakdown: Array<{
    service: string;
    operations: number;
    costUsd: number;
    costNpr: number;
  }>;
  byWorkspace: Record<string, { costUsd: number; costNpr: number }>;
}

interface UsageRecord {
  id: string;
  service: string;
  operation: string;
  quantity: number;
  costUsd: number;
  costNpr: number;
  metadata: Record<string, unknown>;
  timestamp: string;
}

