import Link from "next/link";
import type { ComponentPropsWithoutRef, ReactNode } from "react";

type Variant = "primary" | "secondary" | "ghost";
type Size = "sm" | "md" | "lg";

const base =
  "inline-flex items-center justify-center gap-2 font-medium rounded-full transition-all duration-300 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-iris disabled:opacity-50 disabled:pointer-events-none whitespace-nowrap";

const variants: Record<Variant, string> = {
  primary:
    "bg-gradient-to-r from-iris to-aqua text-white shadow-[0_8px_40px_-8px_rgba(139,92,246,0.6)] hover:shadow-[0_8px_48px_-4px_rgba(139,92,246,0.8)] hover:brightness-110",
  secondary: "glass glass-hover text-chalk",
  ghost: "text-mist hover:text-chalk",
};

const sizes: Record<Size, string> = {
  sm: "text-sm px-4 py-2",
  md: "text-sm px-5 py-2.5",
  lg: "text-base px-7 py-3.5",
};

interface ButtonProps {
  variant?: Variant;
  size?: Size;
  href?: string;
  children: ReactNode;
  className?: string;
  disabled?: boolean;
  onClick?: () => void;
  type?: "button" | "submit" | "reset";
}

export function Button({
  variant = "primary",
  size = "md",
  href,
  children,
  className = "",
  disabled = false,
  onClick,
  type = "button",
}: ButtonProps) {
  const cls = `${base} ${variants[variant]} ${sizes[size]} ${className}`;

  if (!href && !onClick) {
    return (
      <button type={type} disabled={disabled} onClick={onClick} className={cls} aria-disabled={disabled}>
        {children}
      </button>
    );
  }

  if (href) {
    return (
      <Link href={href} className={cls} onClick={onClick} aria-disabled={disabled}>
        {children}
      </Link>
    );
  }

  // href is not set but onClick is - render as button
  return (
    <button type={type} disabled={disabled} onClick={onClick} className={cls} aria-disabled={disabled}>
      {children}
    </button>
  );
}

export function ButtonArrow({
  variant = "primary",
  size = "md",
  href,
  children,
  className = "",
}: {
  variant?: Variant;
  size?: Size;
  href?: string;
  children: ReactNode;
  className?: string;
}) {
  return (
    <Button variant={variant} size={size} href={href} className={className}>
      {children}
      <svg width="14" height="14" viewBox="0 0 14 14" fill="none" aria-hidden>
        <path
          d="M1 7h12m0 0L8 2m5 5L8 12"
          stroke="currentColor"
          strokeWidth="1.6"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    </Button>
  );
}

import { cookies } from "next/headers";
import { getSettings } from "./db";

export interface AuthUser {
  id: string;
  email: string;
  name: string;
  plan: string;
  workspaceId: string;
  role: string;
  profile?: {
    phone?: string;
  };
}

export async function getAuthUser(request: Request): Promise<AuthUser | null> {
  try {
    const cookieStore = await cookies();
    const sessionCookie = cookieStore.get("omni_session");

    if (!sessionCookie?.value) {
      return null;
    }

    // In production, verify the HMAC signature
    // For now, parse the session data
    const sessionData = JSON.parse(Buffer.from(sessionCookie.value, "base64").toString());

    if (sessionData.expires && new Date(sessionData.expires) < new Date()) {
      return null;
    }

    // Get workspace settings to confirm plan
    const settings = getSettings();

    return {
      id: sessionData.userId,
      email: sessionData.email,
      name: sessionData.name,
      plan: settings.plan || "Starter",
      workspaceId: settings.workspaceName || "default",
      role: sessionData.role || "member",
      profile: { phone: settings.phone },
    };
  } catch {
    return null;
  }
}

export async function requireAuth(request: Request): Promise<AuthUser> {
  const user = await getAuthUser(request);
  if (!user) {
    throw new Error("Unauthorized");
  }
  return user;
}

/**
 * Site Crawler API client
 * Supports Firecrawl and Jina AI for parsing HTML, JS & competitor URLs
 * Cost: $0.001 / crawled page
 */

export type CrawlerProvider = "firecrawl" | "jina";

export interface CrawlRequest {
  url: string;
  provider?: CrawlerProvider;
  formats?: ("markdown" | "html" | "links" | "screenshot")[];
  onlyMainContent?: boolean;
  waitFor?: number;
  blockAds?: boolean;
  blockResources?: boolean;
}

export interface CrawlResponse {
  success: boolean;
  data?: {
    url: string;
    title: string;
    description: string;
    markdown: string;
    html: string;
    links: Array<{ url: string; text: string }>;
    metadata: {
      ogTitle?: string;
      ogDescription?: string;
      ogImage?: string;
      twitterCard?: string;
      canonical?: string;
      robots?: string;
      jsonLd?: unknown[];
    };
    screenshot?: string;
  };
  error?: string;
  creditsUsed: number;
}

export interface BulkCrawlRequest {
  urls: string[];
  provider?: CrawlerProvider;
  formats?: ("markdown" | "html" | "links")[];
  onlyMainContent?: boolean;
  webhook?: string;
}

export interface BulkCrawlResponse {
  success: boolean;
  jobId?: string;
  data?: CrawlResponse["data"][];
  error?: string;
  creditsUsed: number;
}

export class CrawlerClient {
  private firecrawlKey: string;
  private jinaKey: string;
  private defaultProvider: CrawlerProvider;

  constructor() {
    this.firecrawlKey = process.env.FIRECRAWL_API_KEY!;
    this.jinaKey = process.env.JINA_API_KEY!;
    this.defaultProvider = (process.env.DEFAULT_CRAWLER_PROVIDER as CrawlerProvider) || "firecrawl";
  }

  async crawl(request: CrawlRequest): Promise<CrawlResponse> {
    const provider = request.provider || this.defaultProvider;

    if (provider === "firecrawl") {
      return this.crawlFirecrawl(request);
    }
    return this.crawlJina(request);
  }

  private async crawlFirecrawl(request: CrawlRequest): Promise<CrawlResponse> {
    const response = await fetch("https://api.firecrawl.dev/v1/scrape", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${this.firecrawlKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        url: request.url,
        formats: request.formats || ["markdown", "links"],
        onlyMainContent: request.onlyMainContent ?? true,
        waitFor: request.waitFor,
        blockAds: request.blockAds ?? true,
        blockResources: request.blockResources ?? true,
      }),
    });

    const data = await response.json();

    if (!data.success) {
      return {
        success: false,
        error: data.error || "Firecrawl scrape failed",
        creditsUsed: 1,
      };
    }

    return {
      success: true,
      data: {
        url: data.data.url,
        title: data.data.metadata?.title || "",
        description: data.data.metadata?.description || "",
        markdown: data.data.markdown || "",
        html: data.data.html || "",
        links: data.data.links?.map((l: { url: string; text: string }) => ({ url: l.url, text: l.text })) || [],
        metadata: {
          ogTitle: data.data.metadata?.ogTitle,
          ogDescription: data.data.metadata?.ogDescription,
          ogImage: data.data.metadata?.ogImage,
          twitterCard: data.data.metadata?.twitterCard,
          canonical: data.data.metadata?.canonical,
          robots: data.data.metadata?.robots,
          jsonLd: data.data.metadata?.jsonLd,
        },
        screenshot: data.data.screenshot,
      },
      creditsUsed: 1,
    };
  }

  private async crawlJina(request: CrawlRequest): Promise<CrawlResponse> {
    const url = new URL("https://r.jina.ai/http://" + request.url.replace(/^https?:\/\//, ""));
    url.searchParams.set("format", "markdown");
    if (request.onlyMainContent !== false) url.searchParams.set("no-images", "true");

    const response = await fetch(url.toString(), {
      headers: {
        Authorization: `Bearer ${this.jinaKey}`,
        Accept: "application/json",
      },
    });

    if (!response.ok) {
      return {
        success: false,
        error: `Jina AI error: ${response.statusText}`,
        creditsUsed: 1,
      };
    }

    const data = await response.json();

    return {
      success: true,
      data: {
        url: request.url,
        title: data.data?.title || "",
        description: data.data?.description || "",
        markdown: data.data?.content || "",
        html: "",
        links: [],
        metadata: {},
      },
      creditsUsed: 1,
    };
  }

  async bulkCrawl(request: BulkCrawlRequest): Promise<BulkCrawlResponse> {
    const provider = request.provider || this.defaultProvider;

    if (provider === "firecrawl") {
      return this.bulkCrawlFirecrawl(request);
    }
    return this.bulkCrawlJina(request);
  }

  private async bulkCrawlFirecrawl(request: BulkCrawlRequest): Promise<BulkCrawlResponse> {
    const response = await fetch("https://api.firecrawl.dev/v1/crawl", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${this.firecrawlKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        urls: request.urls,
        formats: request.formats || ["markdown", "links"],
        onlyMainContent: request.onlyMainContent ?? true,
        webhook: request.webhook,
      }),
    });

    const data = await response.json();

    if (!data.success) {
      return { success: false, error: data.error, creditsUsed: request.urls.length };
    }

    return {
      success: true,
      jobId: data.jobId,
      creditsUsed: request.urls.length,
    };
  }

  private async bulkCrawlJina(request: BulkCrawlRequest): Promise<BulkCrawlResponse> {
    return { success: false, error: "Jina AI bulk crawl not supported", creditsUsed: 0 };
  }
}

let crawlerClient: CrawlerClient | null = null;

export function getCrawlerClient(): CrawlerClient {
  if (!crawlerClient) {
    crawlerClient = new CrawlerClient();
  }
  return crawlerClient;
}

